<script setup lang="ts">import { computed } from 'vue'; import { NButton, NCard, NModal } from 'naive-ui'; import { useChatStore } from '@/stores/hermes/chat'; const chat=useChatStore(); const event=computed(()=>chat.competitionRollbackEvent); function respond(action:'approve'|'rerun'|'cancel'){ const taskId=String(event.value?.taskId||''); if(taskId) chat.respondCompetitionRollback(taskId,action) }</script>
<template><NModal :show="chat.showCompetitionRollbackDialog" preset="card" title="Human rollback approval" style="width:min(520px,calc(100vw - 32px))" @update:show="value => { if (!value) chat.showCompetitionRollbackDialog = false }"><NCard size="small" :bordered="false"><p>{{ event?.message || event?.reason || 'The validator requested human intervention.' }}</p><pre v-if="event?.instructions">{{ event.instructions }}</pre><div class="dialog-actions"><NButton type="primary" @click="respond('approve')">Approve fallback</NButton><NButton secondary @click="respond('rerun')">Rerun task</NButton><NButton tertiary @click="respond('cancel')">Cancel</NButton></div></NCard></NModal></template>
<style scoped>pre{white-space:pre-wrap;font-size:12px;color:var(--text-secondary)}.dialog-actions{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end;margin-top:14px}</style>
